#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
int main() {
  int listenfd = socket(AF_INET, SOCK_STREAM, 0);
  // ... (socket setup and binding) ...
  if (listen(listenfd, 10) == -1) {
    perror("listen failed");
    return 1;
  }
  // ... (accepting connections) ...
  close(listenfd);
  return 0;
}
